import{_ as e,o,c as s,a2 as n}from"./chunks/framework.D21_4UK8.js";const m=JSON.parse('{"title":"🔊 El Rey Indestructible del Tono: La Historia del Electro-Voice EVM-12L","description":"","frontmatter":{},"headers":[],"relativePath":"es/electro-voice-evm12l.md","filePath":"es/electro-voice-evm12l.md"}'),i={name:"es/electro-voice-evm12l.md"};function r(l,a,t,d,c,u){return o(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="🔊-el-rey-indestructible-del-tono-la-historia-del-electro-voice-evm-12l" tabindex="-1">🔊 El Rey Indestructible del Tono: La Historia del Electro-Voice EVM-12L <a class="header-anchor" href="#🔊-el-rey-indestructible-del-tono-la-historia-del-electro-voice-evm-12l" aria-label="Permalink to &quot;🔊 El Rey Indestructible del Tono: La Historia del Electro-Voice EVM-12L&quot;">​</a></h1><h3 id="el-altavoz-de-300-watts-que-definio-el-sonido-de-keith-richards-stevie-ray-vaughan-y-las-grabaciones-mas-legendarias-del-rock" tabindex="-1">El altavoz de 300 Watts que definió el sonido de Keith Richards, Stevie Ray Vaughan y las grabaciones más legendarias del rock. <a class="header-anchor" href="#el-altavoz-de-300-watts-que-definio-el-sonido-de-keith-richards-stevie-ray-vaughan-y-las-grabaciones-mas-legendarias-del-rock" aria-label="Permalink to &quot;El altavoz de 300 Watts que definió el sonido de Keith Richards, Stevie Ray Vaughan y las grabaciones más legendarias del rock.&quot;">​</a></h3><p><strong>Cuadernos de Estudio · Historia del Tono | Main St Audio Labs</strong></p><hr><h2 id="⚡-1-la-antitesis-del-altavoz-britanico" tabindex="-1">⚡ 1. La Antítesis del Altavoz Británico <a class="header-anchor" href="#⚡-1-la-antitesis-del-altavoz-britanico" aria-label="Permalink to &quot;⚡ 1. La Antítesis del Altavoz Británico&quot;">​</a></h2><p>A finales de los años 60 y durante la década del 70, la norma en los amplificadores de rock era la distorsión del propio altavoz. Los clásicos conos británicos de papel liviano (de 25W o 30W) estaban deliberadamente diseñados para flexionar y romperse (<em>speaker breakup</em>), comprimiendo los graves y agregando un grano arenoso en los medios-agudos.</p><p>Sin embargo, cuando los guitarristas comenzaron a exigir amplificadores con mayor ganancia en cascada, transformadores masivos y una potencia limpia descomunal, ocurrió una catástrofe en los escenarios: <strong>los altavoces tradicionales se quemaban, las bobinas se fundían y los acordes abiertos se convertían en una bola de sonido pastoso</strong>.</p><p>En Buchanan, Michigan, la compañía <strong>Electro-Voice (EV)</strong> —líder en sistemas de megafonía para estadios y refuerzo sonoro de alta fidelidad— tenía una visión diametralmente opuesta: <strong>crear un altavoz de guitarra indestructible, capaz de soportar hasta 300 Watts continuos sin deformar la señal ni un solo milímetro</strong>.</p><p>Así nació el legendario <strong>Electro-Voice EVM-12L</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                   CONO TRADICIONAL (25W-30W)       ELECTRO-VOICE EVM-12L (200W-300W)</span></span>
<span class="line"><span>                   ──────────────────────────       ─────────────────────────────────</span></span>
<span class="line"><span>  Comportamiento:  Satura, comprime y rompe.        Lineal, headroom infinito, cero distorsión de cono.</span></span>
<span class="line"><span>  Imán:            Pequeño (1.5 - 2.5 kg).          Cerámico Masivo (7.5 kg / 16 lbs).</span></span>
<span class="line"><span>  Chasis:          Chapa estampada fina.            Fundición de Aluminio Inyectado (Die-Cast).</span></span>
<span class="line"><span>  Bobina:          1.5&quot; hilo redondo común.         2.5&quot; Hilo plano de aluminio de borde (Edgewound).</span></span>
<span class="line"><span>  Sensibilidad:    ~96 - 97 dB SPL.                 100 dB SPL (Volumen atronador e instantáneo).</span></span></code></pre></div><hr><h2 id="🔬-2-anatomia-de-un-tanque-de-guerra-acustico" tabindex="-1">🔬 2. Anatomía de un Tanque de Guerra Acústico <a class="header-anchor" href="#🔬-2-anatomia-de-un-tanque-de-guerra-acustico" aria-label="Permalink to &quot;🔬 2. Anatomía de un Tanque de Guerra Acústico&quot;">​</a></h2><p>El EVM-12L no se parece a ningún otro altavoz de guitarra:</p><ol><li><strong>Chasis de Fundición de Aluminio (<em>Die-Cast Basket</em>):</strong> Mientras que los altavoces comunes usan chapa de acero doblada que puede torsionarse al apretar los tornillos en la madera, el EVM-12L tiene una estructura de aluminio inyectado rígida como una roca.</li><li><strong>Bobina Móvil de 2.5 Pulgadas con Hilo Plano (<em>Edgewound Aluminum</em>):</strong> Enrollada de canto para maximizar la densidad electromagnética en el entrehierro. Esto disipa temperaturas extremas sin quemarse jamás.</li><li><strong>Imán Cerámico Monstruoso de 7.5 kg:</strong> Proporciona un control magnético total sobre la membrana. Cuando la púa toca la cuerda, el cono responde de forma <strong>inmediata</strong> (velocidad de transitorio ultra rápida).</li><li><strong>Sensibilidad de 100 dB SPL @ 1W/1m:</strong> Es tan eficiente convirtiendo energía eléctrica en acústica que conectar un amplificador de 50W a un EVM-12L produce el volumen percibido de un amplificador de 100W con altavoces estándar.</li></ol><hr><h2 id="🎸-3-los-maestros-del-tono-y-sus-secretos" tabindex="-1">🎸 3. Los Maestros del Tono y sus Secretos <a class="header-anchor" href="#🎸-3-los-maestros-del-tono-y-sus-secretos" aria-label="Permalink to &quot;🎸 3. Los Maestros del Tono y sus Secretos&quot;">​</a></h2><h3 id="👅-keith-richards-the-rolling-stones-1978–1981" tabindex="-1">👅 Keith Richards &amp; The Rolling Stones (1978–1981) <a class="header-anchor" href="#👅-keith-richards-the-rolling-stones-1978–1981" aria-label="Permalink to &quot;👅 Keith Richards &amp; The Rolling Stones (1978–1981)&quot;">​</a></h3><p>Durante las sesiones de <em>Some Girls</em>, <em>Emotional Rescue</em> y la consagración de <em>Tattoo You</em>, Keith Richards buscaba una claridad percusiva que los altavoces de rock estándar no podían darle.</p><p>Al tocar en su célebre <strong>afinación de Sol abierto (Open-G de 5 cuerdas)</strong>, Keith necesitaba que cada cuerda vibrara con identidad propia: el chasquido metálico de la púa, el cuerpo de las 6L6 y el ataque de los riffs en <em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em> y <em>&quot;Slave&quot;</em>. Keith y Ronnie Wood equiparon sus combos de madera dura con EVM-12L. El resultado fue ese crujido rítmico arrogante, tridimensional y con mordida de campana que cortaba a través de cualquier mezcla.</p><hr><h3 id="⚡-stevie-ray-vaughan" tabindex="-1">⚡ Stevie Ray Vaughan <a class="header-anchor" href="#⚡-stevie-ray-vaughan" aria-label="Permalink to &quot;⚡ Stevie Ray Vaughan&quot;">​</a></h3><p>Stevie exigía un volumen físico que literalmente destruía los altavoces comunes. Con cuerdas de calibre .013 y afinación en Mi bemol, sus transitorios de púa en temas como <em>&quot;Texas Flood&quot;</em> o <em>&quot;Scuttle Buttin&#39;&quot;</em> empujaban los conos al límite.</p><p>Stevie utilizó el EVM-12L en sus legendarios amplificadores <strong>Dumble Steel String Singer</strong> y en sus combos Fender modificados. El EVM-12L era el único cono que podía entregar ese &quot;golpe en el pecho&quot; en los graves sin ponerse fofo y unos agudos cristalinos que nunca se volvían hirientes.</p><hr><h3 id="🥊-zakk-wylde-ozzy-osbourne-black-label-society" tabindex="-1">🥊 Zakk Wylde (Ozzy Osbourne &amp; Black Label Society) <a class="header-anchor" href="#🥊-zakk-wylde-ozzy-osbourne-black-label-society" aria-label="Permalink to &quot;🥊 Zakk Wylde (Ozzy Osbourne &amp; Black Label Society)&quot;">​</a></h3><p>Para los armónicos artificiales chirriantes y los <em>palm mutes</em> demoledores en afinaciones bajas, Zakk consideraba que los altavoces estándar &quot;se arrugaban&quot; bajo la ganancia. Electro-Voice llegó a fabricar su modelo firma <em>EVM-12L Black Label</em>, catalogado como el altavoz de guitarra más potente y resistente del planeta.</p><hr><h3 id="🎩-joe-bonamassa-eric-johnson" tabindex="-1">🎩 Joe Bonamassa &amp; Eric Johnson <a class="header-anchor" href="#🎩-joe-bonamassa-eric-johnson" aria-label="Permalink to &quot;🎩 Joe Bonamassa &amp; Eric Johnson&quot;">​</a></h3><p>Tanto Bonamassa en sus torres Dumble/Marshall como Eric Johnson para su sonido solista de &quot;violín líquido&quot; han declarado al EVM-12L como el componente insustituible para lograr un <em>sustain</em> infinito donde los armónicos florecen de manera uniforme en todo el mástil.</p><hr><h2 id="🌲-4-el-santo-grial-madera-dura-hardwood-y-sintonia-bass-reflex" tabindex="-1">🌲 4. El Santo Grial: Madera Dura (<em>Hardwood</em>) y Sintonía Bass-Reflex <a class="header-anchor" href="#🌲-4-el-santo-grial-madera-dura-hardwood-y-sintonia-bass-reflex" aria-label="Permalink to &quot;🌲 4. El Santo Grial: Madera Dura (*Hardwood*) y Sintonía Bass-Reflex&quot;">​</a></h2><p>Montar un EVM-12L en una caja endeble de contrachapado fino o con fondo abierto (<em>open back</em>) es desperdiciar la mitad de su potencial.</p><p>El verdadero Santo Grial acústico surgió al alojar este altavoz en <strong>muebles de maderas duras densas (como caoba, bubinga o roble macizo)</strong> equipados con un <strong>puerto inferior sintonizado (<em>bass-reflex</em>)</strong>:</p><ul><li>La madera dura no absorbe energía mecánica, reflejando el 100% de la dinámica hacia el frente.</li><li>El puerto frontal aprovecha la onda trasera del cono para reforzar las frecuencias entre <strong>80 Hz y 160 Hz</strong>.</li><li><strong>El resultado:</strong> Una sola caja 1x12 compacta suena con el peso, la autoridad y la pegada física de un gabinete 4x12 gigante de estadio.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                          ┌─────────────────────────────┐</span></span>
<span class="line"><span>                          │    GABINETE 1x12 HARDWOOD   │</span></span>
<span class="line"><span>                          │                             │</span></span>
<span class="line"><span>                          │         (  EVM-12L  )       │</span></span>
<span class="line"><span>                          │          200W / 300W        │</span></span>
<span class="line"><span>                          │                             │</span></span>
<span class="line"><span>                          │   [==== BASS-PORT ====]     │</span></span>
<span class="line"><span>                          └─────────────────────────────┘</span></span>
<span class="line"><span>                                         │</span></span>
<span class="line"><span>                                         ▼</span></span>
<span class="line"><span>                     ¡RESPUESTA DE GRAVES SECA Y CONTUNDENTE</span></span>
<span class="line"><span>                        SIN BOLA DE GRAVES NI DISTORSIÓN!</span></span></code></pre></div><hr><h2 id="🎛️-5-el-evm-12l-en-el-mundo-digital-la-filosofia-de-tattooyou" tabindex="-1">🎛️ 5. El EVM-12L en el Mundo Digital: La Filosofía de TattooYou <a class="header-anchor" href="#🎛️-5-el-evm-12l-en-el-mundo-digital-la-filosofia-de-tattooyou" aria-label="Permalink to &quot;🎛️ 5. El EVM-12L en el Mundo Digital: La Filosofía de TattooYou&quot;">​</a></h2><p>Muchos simuladores de guitarra fallan porque capturan impulsos (IRs) de altavoces que ya tienen distorsión de papel y problemas de fase. Al sumar la distorsión del previo digital con la distorsión del altavoz, el sonido se vuelve áspero, comprimido y digital.</p><p>En <strong>TattooYou</strong>, elegimos el <strong>1x12 Hardwood con altavoz EVM-12L</strong> precisamente por su pureza acústica:</p><ul><li>Toda la textura, el grano valvular y la compresión que escuchas provienen <strong>100% de las válvulas 6L6 y el circuito neuronal Mark I</strong>.</li><li>Las <strong>24 tomas milimétricas</strong> del módulo <strong>Cab Lab</strong> te permiten microfonear este icono con Shure 57, Neumann 87 y tomas de sala en fase perfecta ($t=0$).</li></ul><hr><p>👉 <a href="/es/guia-microfonos-tomas.html"><strong>Aprende a mezclar las 24 tomas del EVM-12L en la Guía Maestra de Micrófonos y Tomas →</strong></a></p>`,42)])])}const h=e(i,[["render",r]]);export{m as __pageData,h as default};
